const DAY = 86400000;
function hhmm(ms) {//format ms from midnight as HH:mm
    const min = Math.round(ms / 60000);
    return String(Math.floor(min / 60)).padStart(2, "0") + ":" + String(min % 60).padStart(2, "0");
}
function item(from, to, label) {//compute position and width of a bar in percent of the day
    from = Math.max(0, Math.min(DAY, from));
    to = Math.max(from, Math.min(DAY, to));
    return { "from": hhmm(from), "to": hhmm(to), "left": from / DAY * 100, "width": Math.max((to - from) / DAY * 100, 0.5), "label": label };
}
