// Runs every second: starts and stops the irrigation following the schedules cached in flow context
const now = new Date();
const millcurrentday = ((now.getHours() * 60 + now.getMinutes()) * 60 + now.getSeconds()) * 1000 + now.getMilliseconds();//current time in ms from midnight (local time)
const nowms = now.getTime();//absolute time, used for the durations so they work across midnight
const schedules = flow.get("cache.irrigation") || [];
const levelon = global.get("irrigation.output.levelirr") === 1 ? 0 : 1;//relay level that activates the irrigation
const flowrate = global.get("irrigation.config.flowrate");//l/h
const durationms = (ml) => ml * 3600 / flowrate;//time needed to deliver ml at the configured flow rate

if (global.get("irrigation.manualirrigation") !== 0) return;//manual irrigation has the priority
if (!(flowrate > 0)) {
    node.status({ fill: "red", shape: "ring", text: "flow rate not set" });
    return;
}

function stop() {//stop the pump and record the irrigation done
    const delivered = Math.round((nowms - global.get("irrigation.irrtime")) / 1000 * flowrate / 3.6);//ml delivered
    global.set("irrigation.irrisact", 0);
    global.set("irrigation.irrtime", 0);
    node.send([{ "payload": 1 - levelon }, { "topic": "INSERT INTO irrigationdone(id, time, duration) VALUES (NULL, " + millcurrentday + ", " + delivered + ");" }]);
    node.status({ fill: "grey", shape: "ring", text: "stop, " + delivered + " ml" });
}

let active = global.get("irrigation.irrprgact.id");
//leave the program when its time is over, never while the pump is running
if (active > 0 && global.get("irrigation.irrisact") === 0 &&
    (millcurrentday < global.get("irrigation.irrprgact.fromtime") || millcurrentday >= global.get("irrigation.irrprgact.totime"))) {
    global.set("irrigation.irrprgact.id", 0);
    active = 0;
}

if (active === 0 && global.get("irrigation.irrisact") === 1) {//the running program was changed or deleted: stop the pump
    stop();
    return;
}
if (active === 0) {//search the program for the current time
    const p = schedules.find(s => s.active === 1 && millcurrentday >= s.fromtime && millcurrentday < s.totime);
    if (!p) return;
    global.set("irrigation.irrprgact.id", p.id);
    global.set("irrigation.irrprgact.fromtime", p.fromtime);
    global.set("irrigation.irrprgact.duration", p.duration);
    global.set("irrigation.irrprgact.oneshoot", p.oneshoot);
    global.set("irrigation.irrprgact.done", 0);
    if (p.oneshoot === 1) {//one shot: the program lasts the time needed to deliver the duration, plus one minute
        global.set("irrigation.irrprgact.totime", p.fromtime + durationms(p.duration) + 60000);
        global.set("irrigation.irrprgact.every", null);
    } else {
        global.set("irrigation.irrprgact.totime", p.totime);
        global.set("irrigation.irrprgact.every", p.every);
        global.set("irrigation.everytime", nowms - p.every * 60000);//the first irrigation starts immediately
    }
    node.status({ fill: "blue", shape: "dot", text: "program " + p.id });
    return;
}

if (global.get("irrigation.irrisact") === 1) {//pump running: stop it when the duration has been delivered
    if (nowms - global.get("irrigation.irrtime") >= durationms(global.get("irrigation.irrprgact.duration"))) {
        stop();
        if (global.get("irrigation.irrprgact.oneshoot") === 1) global.set("irrigation.irrprgact.done", 1);//one shot runs only once
        else global.set("irrigation.everytime", nowms);
    }
    return;
}

const oneshot = global.get("irrigation.irrprgact.oneshoot") === 1;
const due = oneshot ? global.get("irrigation.irrprgact.done") !== 1
    : nowms >= global.get("irrigation.irrprgact.every") * 60000 + global.get("irrigation.everytime");
if (due) {//start the pump
    global.set("irrigation.irrisact", 1);
    global.set("irrigation.irrtime", nowms);
    node.send([{ "payload": levelon }, null]);
    node.status({ fill: "green", shape: "dot", text: "irrigating, program " + active });
}
return;

