        if ((flow.get("programming.fromtime") > msg.payload[i].fromtime && flow.get("programming.fromtime") > msg.payload[i].totime && flow.get("programming.totime") > msg.payload[i].fromtime && flow.get("programming.totime") > msg.payload[i].totime) || (flow.get("programming.fromtime") < msg.payload[i].fromtime && flow.get("programming.fromtime") < msg.payload[i].totime && flow.get("programming.totime") < msg.payload[i].fromtime && flow.get("programming.totime") < msg.payload[i].totime)) flow.set("programming.conflict", flow.get("programming.conflict"));//if fromtime or / and totime not overlapping other schedule context conflict remain the same 
        else flow.set("programming.conflict", flow.get("programming.conflict") + msg.payload[i].id + ", ");//if fromtime and / or totime overlapping other schedule add id to conflict context for notify
    }
    if (flow.get("programming.conflict") === "") {
        if (flow.get("programming.fromtime") < flow.get("programming.totime")) {//check if fromtime is minor than totime, else notify an error
            msg.topic = "INSERT INTO climate_set(id, active, fromtime, totime, tempmin, tempmax, hummin, hummax) VALUES (NULL, " + flow.get("programming.active") + ", " + flow.get("programming.fromtime") + ", " + flow.get("programming.totime") + ", " + flow.get("programming.tempmin") + ", " + flow.get("programming.tempmax") + ", " + flow.get("programming.hummin") + ", " + flow.get("programming.hummax") + ");";
            node.send([null, msg]);
            setTimeout(function () {
                msg.topic = "SELECT id, active, fromtime, totime, tempmin, tempmax, hummin, hummax FROM climate_set ORDER BY fromtime;";
                node.send([null, msg]);
            }, 200);
        }
        else {
            msg.topic = "Error"
            msg.payload = "From time cannot be greater than To time, the program will not be recorded";
            node.send([msg, null]);
        }  
    }
    else {
        msg.payload = "Current schedule overlapping schedule id " + flow.get("programming.conflict");
        msg.topic = "Error"
        node.send([msg, null]);
    }
}
if (flow.get("programming.cmd") === "delete" && flow.get("programming.id") != undefined) {
    if (global.get("climate.clmprgact.id") === flow.get("programming.id")) global.set("climate.clmprgact.id", 0); //If the currently active program is deleted, climate.clmprgact.id is set to zero in order to update the parameters
    msg.topic = "DELETE FROM climate_set WHERE id = " + flow.get("programming.id") + ";";
    node.send([null, msg]);
    setTimeout(function () {
        msg.topic = "SELECT id, active, fromtime, totime, tempmin, tempmax, hummin, hummax FROM climate_set ORDER BY fromtime;";
        node.send([null, msg]);
    }, 200);
}
return;

function hhmm(ms) {//ms from midnight to HH:mm
    const min = Math.round(ms / 60000) % 1440;
    return String(Math.floor(min / 60)).padStart(2, "0") + ":" + String(min % 60).padStart(2, "0");
}
for (let i = 0; i < msg.payload.length; i++) {
    msg.payload[i].fromtime = hhmm(msg.payload[i].fromtime);
    msg.payload[i].totime = hhmm(msg.payload[i].totime);
}
return msg;

// Runs every second: drives heating and fan following the schedules cached in flow context
const now = new Date();
const millcurrentday = ((now.getHours() * 60 + now.getMinutes()) * 60 + now.getSeconds()) * 1000 + now.getMilliseconds();//current time in ms from midnight (local time)
const schedules = flow.get("cache.climate") || [];
const temp = global.get("climate.inttemp");
const hum = global.get("climate.inthum");

if (global.get("climate.manualheat") !== 0 || global.get("climate.manualfan") !== 0) return;//manual commands have the priority

const outputs = {//output index, global flag, relay level setting, label for the log
    "heat": { "index": 0, "flag": "climate.heatisact", "level": "climate.output.levelheat", "label": "Heating" },
    "fan": { "index": 1, "flag": "climate.fanisact", "level": "climate.output.levelfan", "label": "Fan" }
};
function setOutput(name, on, reason) {//switch an output only when its state changes, log the action
    const o = outputs[name];
    if ((global.get(o.flag) === 1) === on) return;
    global.set(o.flag, on ? 1 : 0);
    const levelinactive = global.get(o.level) === 1 ? 1 : 0;
    const pin = [null, null, null];
    pin[o.index] = { "payload": on ? 1 - levelinactive : levelinactive };
    pin[2] = { "topic": "INSERT INTO climate_actions(id, time, inttemp, inthum, action) VALUES (NULL, " + millcurrentday + ", " +
        (typeof temp === "number" ? temp : "NULL") + ", " + (typeof hum === "number" ? hum : "NULL") + ", \"" + o.label + (on ? " start" : " stop") + (reason ? ", " + reason : "") + "\");" };
    node.send(pin);
}

//sensor watchdog: data older than 5 minutes is not valid, stop the outputs (failsafe)
const sensorok = global.get("climate.testmode") === true || (Date.now() - global.get("climate.lastread")) < 300000;
if (!sensorok) {
    setOutput("heat", false, "sensor offline");
    setOutput("fan", false, "sensor offline");
    global.set("climate.clmprgact.id", 0);
    node.status({ fill: "red", shape: "dot", text: "sensor offline" });
    return;
}

let active = global.get("climate.clmprgact.id");
if (active > 0 && (millcurrentday < global.get("climate.clmprgact.fromtime") || millcurrentday >= global.get("climate.clmprgact.totime"))) {
    global.set("climate.clmprgact.id", 0);//program time is over
    active = 0;
}
if (active === 0) {//search the program for the current time
    const p = schedules.find(s => s.active === 1 && millcurrentday >= s.fromtime && millcurrentday < s.totime);
    if (!p) {//no program: the outputs driven by a program are stopped
        setOutput("heat", false, "no program");
        setOutput("fan", false, "no program");
        node.status({ fill: "grey", shape: "ring", text: "no program" });
        return;
    }
    global.set("climate.clmprgact.id", p.id);
    global.set("climate.clmprgact.fromtime", p.fromtime);
    global.set("climate.clmprgact.totime", p.totime);
    global.set("climate.clmprgact.tempmin", p.tempmin);
    global.set("climate.clmprgact.tempmax", p.tempmax);
    global.set("climate.clmprgact.hummin", p.hummin);
    global.set("climate.clmprgact.hummax", p.hummax);
}

//temperature and humidity compared with the limits of the program (limits included in the range)
const tstate = temp < global.get("climate.clmprgact.tempmin") ? "low" : (temp > global.get("climate.clmprgact.tempmax") ? "high" : "ok");
const hstate = hum < global.get("climate.clmprgact.hummin") ? "low" : (hum > global.get("climate.clmprgact.hummax") ? "high" : "ok");
//heating when cold, or when temperature is fine but the air is too dry; fan when too hot or too humid
setOutput("heat", tstate === "low" || (tstate === "ok" && hstate === "low"));
setOutput("fan", tstate === "high" || hstate === "high");
node.status({ fill: "blue", shape: "dot", text: "program " + global.get("climate.clmprgact.id") + ": T " + tstate + ", RH " + hstate });
return;

if (msg.payload === "change" && msg.name === "Climate") {
    let msgout = {"topic" : ""}
    msgout.topic = "SELECT id , time, inttemp, inthum, action FROM climate_actions ORDER BY time;";
    node.send(msgout);
}
return;

