if (msg.statusCode !== 200 || !msg.payload || typeof msg.payload.value !== "number") {
    node.status({ fill: "red", shape: "ring", text: "dry bulb read failed" });
    return;
}
msg.drybulb = msg.payload.value;
msg.url = "http://" + msg.sensorhost + "/sensor/bulbo_umido";
return msg;

if (msg.statusCode !== 200 || !msg.payload || typeof msg.payload.value !== "number" || typeof msg.drybulb !== "number") {
    node.status({ fill: "red", shape: "ring", text: "wet bulb read failed" });
    return;
}
const t = msg.drybulb;//dry bulb temperature °C
const tw = Math.min(msg.payload.value, t);//wet bulb temperature °C, it cannot be higher than the dry bulb
const es = (x) => 0.6108 * Math.exp(17.27 * x / (x + 237.3));//saturation vapour pressure in kPa (Tetens)
const pressure = 101.325 * Math.pow(1 - 2.25577e-5 * (global.get("climate.config.altitude") || 0), 5.25588);//air pressure in kPa at the altitude
const e = Math.max(es(tw) - 0.000662 * pressure * (t - tw), 0.001);//actual vapour pressure in kPa (aspirated psychrometer)
const rh = Math.max(0, Math.min(100, 100 * e / es(t)));//relative humidity %
const a = Math.log(e / 0.6108);
const dewpoint = 237.3 * a / (17.27 - a);//dew point °C
const vpd = Math.max(es(t) - e, 0);//vapour pressure deficit of the air in kPa
const round = (v, d) => Math.round(v * Math.pow(10, d)) / Math.pow(10, d);

global.set("climate.inttemp", round(t, 1));
global.set("climate.wetbulb", round(tw, 1));
global.set("climate.inthum", round(rh, 0));
global.set("climate.dewpoint", round(dewpoint, 1));
global.set("climate.vpd", round(vpd, 2));
global.set("climate.lastread", Date.now());
node.status({ fill: "green", shape: "dot", text: round(t, 1) + " °C " + round(rh, 0) + " % VPD " + round(vpd, 2) + " kPa" });

const tochart = { "payload": { "inttemp": round(t, 1), "inthum": round(rh, 0), "dewpoint": round(dewpoint, 1), "vpd": round(vpd, 2) } };
const todb = { "topic": "INSERT INTO climate_detected(id, date, intemperature, inhumidity, exttemperature, exthumidity) VALUES (NULL, " + Date.now() + ", " + round(t, 1) + ", " + round(rh, 0) + ", NULL, NULL);" };
return [tochart, todb];

